<?php
declare(strict_types=1);

const I18N_DEFAULT_LOCALE = 'en';
const I18N_SUPPORTED_LOCALES = ['en', 'fr', 'ar', 'es'];

function i18n_supported_locales(): array
{
    return I18N_SUPPORTED_LOCALES;
}

function i18n_locale_labels(): array
{
    return [
        'en' => 'English',
        'fr' => 'Français',
        'ar' => 'العربية',
        'es' => 'Español',
    ];
}

function i18n_normalize_locale(?string $locale): string
{
    $locale = strtolower(trim((string) $locale));
    $locale = str_replace('_', '-', $locale);
    $locale = substr($locale, 0, 2);

    return in_array($locale, I18N_SUPPORTED_LOCALES, true) ? $locale : I18N_DEFAULT_LOCALE;
}

function i18n_current_locale(): string
{
    static $locale = null;

    if ($locale !== null) {
        return $locale;
    }

    $requested = $_GET['lang'] ?? null;
    if (is_string($requested) && in_array(i18n_normalize_locale($requested), I18N_SUPPORTED_LOCALES, true)) {
        $locale = i18n_normalize_locale($requested);
        setcookie('marocpc_lang', $locale, [
            'expires' => time() + (365 * 24 * 3600),
            'path' => '/',
            'secure' => !empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off',
            'httponly' => false,
            'samesite' => 'Lax',
        ]);
        $_COOKIE['marocpc_lang'] = $locale;
        return $locale;
    }

    if (!empty($_COOKIE['marocpc_lang'])) {
        $locale = i18n_normalize_locale((string) $_COOKIE['marocpc_lang']);
        return $locale;
    }

    $accept = $_SERVER['HTTP_ACCEPT_LANGUAGE'] ?? '';
    if (is_string($accept) && $accept !== '') {
        foreach (explode(',', $accept) as $candidate) {
            $candidateLocale = i18n_normalize_locale(explode(';', $candidate)[0] ?? '');
            if (in_array($candidateLocale, I18N_SUPPORTED_LOCALES, true)) {
                $locale = $candidateLocale;
                return $locale;
            }
        }
    }

    $locale = I18N_DEFAULT_LOCALE;
    return $locale;
}

function i18n_direction(?string $locale = null): string
{
    return ($locale ?? i18n_current_locale()) === 'ar' ? 'rtl' : 'ltr';
}

function i18n_currency_symbol(?string $locale = null): string
{
    $locale = $locale ?? i18n_current_locale();
    return $locale === 'ar' ? 'درهم' : 'DH';
}

function i18n_format_money(float $amount, ?string $locale = null): string
{
    $locale = $locale ?? i18n_current_locale();
    $symbol = i18n_currency_symbol($locale);
    return number_format($amount, 2, '.', ',') . ' ' . $symbol;
}

function i18n_catalog(string $locale): array
{
    static $catalogs = [];

    $locale = i18n_normalize_locale($locale);
    if (isset($catalogs[$locale])) {
        return $catalogs[$locale];
    }

    $file = dirname(__DIR__) . DIRECTORY_SEPARATOR . 'lang' . DIRECTORY_SEPARATOR . $locale . '.php';
    $catalog = is_readable($file) ? require $file : [];

    $closurePath = __DIR__ . DIRECTORY_SEPARATOR . 'i18n_catalog_audit_closure.php';
    if (is_file($closurePath)) {
        require_once $closurePath;
        if (function_exists('i18n_catalog_audit_closure_map')) {
            $catalog = array_replace_recursive(i18n_catalog_audit_closure_map($locale), $catalog);
        }
    }

    $catalogs[$locale] = $catalog;

    return $catalogs[$locale];
}

function i18n_lookup(array $catalog, string $key): ?string
{
    $value = $catalog;
    foreach (explode('.', $key) as $segment) {
        if (!is_array($value) || !array_key_exists($segment, $value)) {
            return null;
        }
        $value = $value[$segment];
    }

    return is_string($value) ? $value : null;
}

function i18n_report_missing_catalog_key(string $key, string $locale): void
{
    static $reported = [];

    if ($locale === '' || $locale === I18N_DEFAULT_LOCALE) {
        return;
    }

    $dedupeKey = $locale . "\0" . $key;
    if (isset($reported[$dedupeKey])) {
        return;
    }
    $reported[$dedupeKey] = true;

    $message = "[i18n] Missing catalog key: '{$key}' locale: '{$locale}'";
    error_log($message);

    if (defined('DEV_MODE') && DEV_MODE && !($GLOBALS['I18N_JS_CONTEXT'] ?? false)) {
        trigger_error($message, E_USER_WARNING);
    }
}

function i18n_t(string $key, array $params = [], ?string $fallback = null): string
{
    $locale = i18n_current_locale();
    $localizedValue = i18n_lookup(i18n_catalog($locale), $key);
    if ($localizedValue === null) {
        i18n_report_missing_catalog_key($key, $locale);
    }

    $value = $localizedValue
        ?? i18n_lookup(i18n_catalog(I18N_DEFAULT_LOCALE), $key)
        ?? $fallback
        ?? $key;

    foreach ($params as $name => $replacement) {
        $value = str_replace('{' . $name . '}', (string) $replacement, $value);
    }

    return $value;
}

function i18n_e(string $key, array $params = [], ?string $fallback = null): void
{
    echo htmlspecialchars(i18n_t($key, $params, $fallback), ENT_QUOTES, 'UTF-8');
}

function i18n_url(string $url, ?string $locale = null): string
{
    $locale ??= i18n_current_locale();

    if ($locale === I18N_DEFAULT_LOCALE || preg_match('/^(https?:|mailto:|tel:|#)/i', $url)) {
        return $url;
    }

    $parts = parse_url($url);
    if ($parts === false) {
        return $url;
    }

    $query = [];
    if (!empty($parts['query'])) {
        parse_str($parts['query'], $query);
    }
    $query['lang'] = $locale;

    $rebuilt = $parts['path'] ?? '';
    $queryString = http_build_query($query);
    if ($queryString !== '') {
        $rebuilt .= '?' . $queryString;
    }
    if (!empty($parts['fragment'])) {
        $rebuilt .= '#' . $parts['fragment'];
    }

    return $rebuilt;
}

function i18n_current_url_for(string $locale): string
{
    $path = parse_url($_SERVER['REQUEST_URI'] ?? 'index.php', PHP_URL_PATH) ?: 'index.php';
    $query = $_GET;
    $query['lang'] = i18n_normalize_locale($locale);

    $queryString = http_build_query($query);
    return $path . ($queryString !== '' ? '?' . $queryString : '');
}

function i18n_query_hidden_inputs(): string
{
    $html = '';
    foreach ($_GET as $key => $value) {
        if ($key === 'lang' || is_array($value)) {
            continue;
        }
        $html .= '<input type="hidden" name="' . htmlspecialchars((string) $key, ENT_QUOTES, 'UTF-8') . '" value="' . htmlspecialchars((string) $value, ENT_QUOTES, 'UTF-8') . '">' . "\n";
    }

    return $html;
}

function i18n_flatten_catalog_strings(array $catalog, string $prefix = '', array &$strings = []): void
{
    foreach ($catalog as $key => $value) {
        $path = $prefix === '' ? (string) $key : $prefix . '.' . (string) $key;
        if (is_array($value)) {
            i18n_flatten_catalog_strings($value, $path, $strings);
            continue;
        }

        if (is_string($value) && trim($value) !== '') {
            $strings[$path] = $value;
        }
    }
}

function i18n_catalog_phrase_map(string $locale): array
{
    static $phraseMaps = [];

    $locale = i18n_normalize_locale($locale);
    if ($locale === I18N_DEFAULT_LOCALE) {
        return [];
    }
    if (isset($phraseMaps[$locale])) {
        return $phraseMaps[$locale];
    }

    $sourceStrings = [];
    $targetStrings = [];
    i18n_flatten_catalog_strings(i18n_catalog(I18N_DEFAULT_LOCALE), '', $sourceStrings);
    i18n_flatten_catalog_strings(i18n_catalog($locale), '', $targetStrings);

    $map = [];
    foreach ($sourceStrings as $key => $source) {
        $target = $targetStrings[$key] ?? null;
        if (!is_string($target) || trim($source) === '' || $source === $target) {
            continue;
        }
        if (!isset($map[$source])) {
            $map[$source] = $target;
        }
    }

    $phraseMaps[$locale] = $map;
    return $phraseMaps[$locale];
}

