        static fn(string $value, string $key): bool => $value !== $key,
        ARRAY_FILTER_USE_BOTH
    );
    $auditClosureMap = i18n_admin_audit_closure_phrase_map($locale);

    return array_merge($baseMap, $homeMap, $builderMap, $runtimeMap, $missingMap, $adminStockMap[$locale] ?? [], $adminVisitorsMap[$locale] ?? [], $auditClosureMap);
}

