function i18n_builder_runtime_phrase_map(string $locale): array
{
    $maps = [
        'fr' => [
            'Your trusted source for premium computer hardware. Building dreams, one component at a time.' => 'Votre source de confiance pour du materiel informatique premium. Nous construisons vos projets, composant par composant.',
            '1080p is best for budget and high refresh rates, 1440p is the sweet spot for most gaming PCs, and 4K needs a stronger GPU for smooth ultra settings.' => 'Le 1080p est ideal pour les budgets serres et les hautes frequences, le 1440p est le meilleur equilibre pour la plupart des PC gaming, et la 4K demande un GPU plus puissant pour des reglages ultra fluides.',
            'Yes. Choose up to 4 titles and the finder will size the build around the most demanding game in your selection.' => 'Oui. Choisissez jusqu a 4 jeux et le chercheur dimensionnera la config autour du jeu le plus exigeant de votre selection.',
            'It is a practical catalog-based estimate using the selected CPU, GPU, games, and resolution. Real FPS can vary by settings, drivers, patches, and thermals.' => 'C est une estimation pratique basee sur le catalogue, le CPU, le GPU, les jeux et la resolution choisis. Les FPS reels peuvent varier selon les reglages, pilotes, mises a jour et temperatures.',
            'Use the component wizard to swap in parts similar to your current CPU or GPU, then compare the FPS panel against the recommended build.' => 'Utilisez l assistant de composants pour choisir des pieces proches de votre CPU ou GPU actuel, puis comparez le panneau FPS avec la config recommandee.',
            'Not always. A 1440p or 4K build shines most when your monitor supports that resolution and refresh rate, so match the PC to the screen you actually use.' => 'Pas toujours. Une config 1440p ou 4K est surtout utile si votre ecran prend en charge cette resolution et cette frequence, donc adaptez le PC a l ecran que vous utilisez vraiment.',
