        'ar' => [
            'Your trusted source for premium computer hardware. Building dreams, one component at a time.' => 'مصدرُك الموثوق لأجهزة الكمبيوتر عالية الجودة. نبني أحلامك، مكونا تلو الآخر.',
            '1080p is best for budget and high refresh rates, 1440p is the sweet spot for most gaming PCs, and 4K needs a stronger GPU for smooth ultra settings.' => 'دقة 1080p هي الأفضل للميزانيات المحدودة ومعدلات التحديث العالية، و1440p هي نقطة التوازن لمعظم أجهزة الألعاب، أما 4K فتحتاج بطاقة رسومية أقوى لإعدادات ألترا بسلاسة.',
            'Yes. Choose up to 4 titles and the finder will size the build around the most demanding game in your selection.' => 'نعم. اختر حتى 4 ألعاب وسيضبط الباحث التجميعة حسب أكثر لعبة تطلبا في اختيارك.',
            'It is a practical catalog-based estimate using the selected CPU, GPU, games, and resolution. Real FPS can vary by settings, drivers, patches, and thermals.' => 'هو تقدير عملي مبني على الكتالوج والمعالج وبطاقة الرسوميات والألعاب والدقة المختارة. قد تختلف FPS الفعلية حسب الإعدادات والتعريفات والتحديثات والحرارة.',
            'Use the component wizard to swap in parts similar to your current CPU or GPU, then compare the FPS panel against the recommended build.' => 'استخدم مساعد المكونات لاختيار قطع مشابهة لمعالجك أو بطاقتك الحالية، ثم قارن لوحة FPS مع التجميعة المقترحة.',
            'Not always. A 1440p or 4K build shines most when your monitor supports that resolution and refresh rate, so match the PC to the screen you actually use.' => 'ليس دائما. تجميعة 1440p أو 4K تظهر فائدتها عندما تدعم شاشتك تلك الدقة ومعدل التحديث، لذلك طابق الحاسوب مع الشاشة التي تستخدمها فعلا.',
            'Performance headroom' => 'هامش أداء',
