        'es' => [
            'Your trusted source for premium computer hardware. Building dreams, one component at a time.' => 'Tu fuente de confianza para hardware informatico premium. Construimos tus ideas, componente a componente.',
            '1080p is best for budget and high refresh rates, 1440p is the sweet spot for most gaming PCs, and 4K needs a stronger GPU for smooth ultra settings.' => '1080p es ideal para presupuesto y alta tasa de refresco, 1440p es el punto equilibrado para la mayoria de PCs gaming, y 4K necesita una GPU mas fuerte para ultra fluido.',
            'Yes. Choose up to 4 titles and the finder will size the build around the most demanding game in your selection.' => 'Si. Elige hasta 4 juegos y el buscador dimensionara la build segun el juego mas exigente de tu seleccion.',
            'It is a practical catalog-based estimate using the selected CPU, GPU, games, and resolution. Real FPS can vary by settings, drivers, patches, and thermals.' => 'Es una estimacion practica basada en catalogo con CPU, GPU, juegos y resolucion seleccionados. Los FPS reales pueden variar por ajustes, drivers, parches y temperaturas.',
            'Use the component wizard to swap in parts similar to your current CPU or GPU, then compare the FPS panel against the recommended build.' => 'Usa el asistente de componentes para elegir piezas similares a tu CPU o GPU actual, luego compara el panel FPS con la build recomendada.',
            'Not always. A 1440p or 4K build shines most when your monitor supports that resolution and refresh rate, so match the PC to the screen you actually use.' => 'No siempre. Una build 1440p o 4K luce mas cuando tu monitor soporta esa resolucion y refresco, asi que adapta el PC a la pantalla que usas.',
